package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.graphics.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

/** Visible-only, manual-city forecast. Cache is explicitly labelled, never a fake live reading. */
public final class WeatherActivity extends LeoActivity {
 private Face face;private JSONObject data;private String city=L.t("București"),status="",locationKey="";private double latitude=44.43225,longitude=26.10626;private long updated;private int page,day,request;private boolean busy;
 protected void onCreate(Bundle b){super.onCreate(b);SharedPreferences p=getSharedPreferences("weather",0);city=p.getString("city",city);latitude=Double.longBitsToDouble(p.getLong("lat",Double.doubleToLongBits(latitude)));longitude=Double.longBitsToDouble(p.getLong("lon",Double.doubleToLongBits(longitude)));updated=p.getLong("updated",0);try{String s=p.getString("data","");if(!s.isEmpty())data=new JSONObject(s);}catch(JSONException ignored){}locationKey=city;face=new Face();setContentView(face);if(data==null||System.currentTimeMillis()-updated>1800000)refresh();}
 protected void onDestroy(){request++;super.onDestroy();}
 private void post(Runnable r){if(!isDestroyed()&&!isFinishing())ui(r);}
 private void refresh(){if(busy)return;busy=true;status=L.t("Se actualizează…");face.invalidate();final int token=++request;final double lat=latitude,lon=longitude;worker.execute(new Runnable(){public void run(){try{final JSONObject next=WeatherData.forecast(lat,lon);post(new Runnable(){public void run(){if(token!=request)return;data=next;updated=System.currentTimeMillis();busy=false;status="";save();face.invalidate();}});}catch(Exception e){post(new Runnable(){public void run(){if(token!=request)return;busy=false;status=L.t("Actualizare eșuată · vezi cache");face.invalidate();}});}}});}
 private void save(){getSharedPreferences("weather",0).edit().putString("city",city).putLong("lat",Double.doubleToLongBits(latitude)).putLong("lon",Double.doubleToLongBits(longitude)).putLong("updated",updated).putString("data",data==null?"":data.toString()).apply();}
 private void search(){LinearLayout fields=fields(L.t("Caută oraș"));final EditText query=field(fields,L.t("Oraș / oraș, țară"),city,InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){final String term=query.getText().toString().trim();if(term.length()<2||term.length()>100){notice(L.t("Scrie între 2 și 100 de caractere"));return;}if(busy){notice(L.t("Așteaptă actualizarea"));return;}busy=true;final int token=++request;notice(L.t("Caut orașul…"));worker.execute(new Runnable(){public void run(){try{final JSONArray results=WeatherData.search(term);post(new Runnable(){public void run(){if(token!=request)return;busy=false;if(results==null||results.length()==0){notice(L.t("Niciun oraș găsit"));return;}String[] names=new String[results.length()];for(int i=0;i<names.length;i++){JSONObject o=results.optJSONObject(i);names[i]=o.optString("name")+" · "+o.optString("admin1")+" · "+o.optString("country_code");}options(L.t("Alege localitatea"),names,new Choice(){public void pick(int i){JSONObject o=results.optJSONObject(i);city=o.optString("name");latitude=o.optDouble("latitude");longitude=o.optDouble("longitude");data=null;updated=0;day=0;save();showFace();refresh();}});}});}catch(Exception e){post(new Runnable(){public void run(){if(token!=request)return;busy=false;notice(L.t("Căutare indisponibilă; verifică Internetul"));}});}}});}};back=new Runnable(){public void run(){showFace();}};footer(L.t("Caută"),L.t("Următor"),L.t("Șterge"));query.requestFocus();}
 private void showFace(){form=false;left=null;back=null;setContentView(face);face.requestFocus();face.invalidate();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(face.getWindowToken(),0);}
 private void menu(){options(L.t("Meteo"),new String[]{L.t("Actualizează"),L.t("Schimbă orașul"),L.t("Despre date și confidențialitate")},new Choice(){public void pick(int i){if(i==0)refresh();else if(i==1)search();else options(L.t("Sursa prognozei"),new String[]{"Open-Meteo · CC BY 4.0",L.t("Localități · GeoNames"),L.t("Date modelate, nu senzor local"),L.t("Oraș transmis la căutare"),L.t("Coordonate trimise la prognoză")},new Choice(){public void pick(int n){}});}});}
 public boolean onKeyDown(int key,KeyEvent e){if(form)return super.onKeyDown(key,e);if(key==KeyEvent.KEYCODE_BACK){finish();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){if(e.getRepeatCount()==0)page=(page+(key==KeyEvent.KEYCODE_DPAD_RIGHT?1:2))%3;face.invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){day=Math.max(0,Math.min(6,day+(key==KeyEvent.KEYCODE_DPAD_DOWN?1:-1)));face.invalidate();return true;}if(key==KeyEvent.KEYCODE_MENU){if(e.getRepeatCount()==0)menu();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0){if(page==1){page=2;face.invalidate();}else refresh();}return true;}return super.onKeyDown(key,e);}
 private String daily(String key,int index,String suffix){JSONObject d=data==null?null:data.optJSONObject("daily");JSONArray a=d==null?null:d.optJSONArray(key);if(a==null||a.isNull(index))return "—";Object value=a.opt(index);if(value instanceof Number)return Math.round(((Number)value).doubleValue())+suffix;String s=a.optString(index);return s.contains("T")?s.substring(s.indexOf('T')+1):s;}
 private int code(int index){JSONObject d=data==null?null:data.optJSONObject("daily");JSONArray a=d==null?null:d.optJSONArray("weather_code");return a==null?-1:a.optInt(index,-1);}
 private final class Face extends View {
  final Paint p=new Paint(3);Face(){super(WeatherActivity.this);setFocusable(true);requestFocus();}public boolean isOpaque(){return true;}
  void text(Canvas c,String s,int x,int y,int size,int color,Paint.Align align){p.setStyle(Paint.Style.FILL);p.setColor(color);p.setTextSize(size);p.setTextAlign(align);int limit=align==Paint.Align.CENTER?220:210;if(p.measureText(s)>limit){int n=p.breakText(s,true,limit-p.measureText("…"),null);s=s.substring(0,n)+"…";}c.drawText(s,x,y,p);}
  void card(Canvas c,int y,int h,boolean selected){p.setColor(selected?Appearance.mix(palette.card,palette.accent,.22f):palette.card);c.drawRoundRect(8,y,232,y+h,5,5,p);}
  void weatherIcon(Canvas c,int code){p.setColor(0xffffc84d);c.drawCircle(83,109,18,p);if(code>0){p.setColor(0xffa7d5ed);c.drawCircle(96,118,15,p);c.drawCircle(77,124,11,p);c.drawRoundRect(73,119,115,135,8,8,p);}if(code>=51){p.setColor(0xff63c7ff);p.setStrokeWidth(3);for(int x=80;x<111;x+=11)c.drawLine(x,141,x-4,148,p);}}
  protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/302f);c.drawColor(palette.background);UiChrome.header(c,L.t("Meteo · ")+city,palette,p);String[] tabs={L.t("Acum"),L.t("7 zile"),L.t("Detalii")};for(int i=0;i<3;i++){if(i==page){p.setColor(palette.card);c.drawRect(i*80,34,i*80+80,59,p);p.setColor(palette.accent);c.drawRect(i*80,57,i*80+80,59,p);}text(c,tabs[i],40+i*80,50,13,i==page?palette.accent:Color.WHITE,Paint.Align.CENTER);}JSONObject current=data==null?null:data.optJSONObject("current");
   if(data==null){text(c,busy?L.t("Încarc prognoza…"):L.t("Prognoză indisponibilă"),120,142,18,Color.WHITE,Paint.Align.CENTER);text(c,L.t("Opțiuni: oraș / actualizare"),120,174,12,palette.accent,Paint.Align.CENTER);}else if(page==0){card(c,72,119,false);weatherIcon(c,current.optInt("weather_code",-1));text(c,WeatherData.number(current,"temperature_2m","°"),170,131,43,Color.WHITE,Paint.Align.CENTER);text(c,WeatherData.code(current.optInt("weather_code",-1)),120,172,16,palette.accent,Paint.Align.CENTER);text(c,L.t("Resimțită ")+WeatherData.number(current,"apparent_temperature","°C")+L.t(" · umid. ")+WeatherData.number(current,"relative_humidity_2m","%"),120,211,12,Color.WHITE,Paint.Align.CENTER);text(c,L.t("Vânt ")+WeatherData.number(current,"wind_speed_10m"," km/h"),120,232,13,Color.WHITE,Paint.Align.CENTER);text(c,L.t("Azi ")+daily("temperature_2m_min",0,"°")+" / "+daily("temperature_2m_max",0,"°")+L.t(" · ploaie ")+daily("precipitation_probability_max",0,"%"),120,252,12,palette.accent,Paint.Align.CENTER);}else if(page==1){int first=Math.max(0,Math.min(3,day-2));for(int i=first;i<Math.min(7,first+4);i++){int y=70+(i-first)*44;card(c,y,39,i==day);text(c,daily("time",i,"")+" · "+daily("temperature_2m_min",i,"°")+" / "+daily("temperature_2m_max",i,"°"),16,y+16,12,Color.WHITE,Paint.Align.LEFT);text(c,WeatherData.code(code(i))+" · "+daily("precipitation_probability_max",i,"%"),16,y+32,11,palette.accent,Paint.Align.LEFT);}text(c,L.t("↑ ↓ ziua · OK detalii"),120,260,11,palette.accent,Paint.Align.CENTER);}else{card(c,74,158,false);text(c,daily("time",day,""),120,98,19,Color.WHITE,Paint.Align.CENTER);text(c,WeatherData.code(code(day)),120,123,16,palette.accent,Paint.Align.CENTER);text(c,"Min / max · "+daily("temperature_2m_min",day,"°")+" / "+daily("temperature_2m_max",day,"°"),120,150,14,Color.WHITE,Paint.Align.CENTER);text(c,L.t("Prob. precipitații · ")+daily("precipitation_probability_max",day,"%"),120,174,13,Color.WHITE,Paint.Align.CENTER);text(c,L.t("Răsărit ")+daily("sunrise",day,"")+L.t(" · apus ")+daily("sunset",day,""),120,199,13,Color.WHITE,Paint.Align.CENTER);text(c,data.optString("timezone"),120,222,11,palette.accent,Paint.Align.CENTER);}
   String freshness=updated==0?status:(!status.isEmpty()?status:"Cache · "+new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(updated)));p.setColor(palette.bar);c.drawRect(0,275,240,302,p);text(c,freshness,120,272,9,0xffbbc2d4,Paint.Align.CENTER);text(c,L.t("Opțiuni"),7,294,11,Color.WHITE,Paint.Align.LEFT);text(c,page==1?L.t("Detalii"):busy?L.t("Așteaptă"):L.t("Actualiz."),120,294,12,palette.accent,Paint.Align.CENTER);text(c,L.t("Înapoi"),233,294,11,Color.WHITE,Paint.Align.RIGHT);c.restore();}
 }
}
